{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Bilastine, the closest analogue by Morgan similarity, has an absolute oral bioavailability of 61% in humans, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Paltusotine, a heteroaromatic nitrile-containing drug with moderate structural similarity, showed 69% absolute oral bioavailability in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Linagliptin, which shares an N-methylated heteroaromatic core and has lower bioavailability among the analogues, still achieves approximately 29.5% absolute oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Rutaecarpine, a lipophilic fused heteroaromatic alkaloid, has low oral bioavailability; this is contradictory evidence, but its very low similarity and distinct solubility-limited phenotype limit transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tariquidar has low oral bioavailability in humans, providing contradictory evidence; however, its large basic amine and P-glycoprotein substrate profile are not shared by the query, reducing transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable human absolute bioavailability evidence from structurally related heteroaromatic drugs supports F >= 20%, despite an unfavorable solubility prior. Low-bioavailability analogues are less structurally transferable and do not outweigh the consistent high-bioavailability observations.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities are modest, so structural transfer is uncertain.",
    "The query's very high lipophilicity and poor predicted solubility may cause dose- or formulation-dependent bioavailability not captured by analogue data.",
    "Potential efflux transporter liability is not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

